flowchart LR
  Start@{shape: sm-circ, label: "$$x_0$$"}
  Stop@{shape: fr-circ, label: "$$x_1$$"}
  Fork@{shape: fork, label: "$$x_2$$"}
  Collate@{shape: hourglass, label: "$$x_3$$"}
  Signal@{shape: bolt, label: "$$x_4$$"}
  Junction@{shape: f-circ, label: "$$x_5$$"}
  Summary@{shape: cross-circ, label: "$$x_6$$"}
  Bang@{shape: bang, label: "**Batch complete**<br/>Notify subscribers", labelType: markdown}
  Caption@{shape: text, label: "**Audit**<br/>Preserve event order", labelType: markdown}
  Start --> Fork
  Fork -->|ordered| Collate
  Fork -.->|streaming| Signal
  Collate --> Junction
  Signal --x Junction
  Junction ==> Summary
  Summary --> Bang
  Bang --> Stop
  Caption --- Bang
  Summary -. retry .-> Fork
  class Junction,Summary accent
  classDef accent fill:#fee,stroke:#b44,stroke-width:2px

